class Strategy:
    """FedDynM: Dynamic regularization (FedDyn-style) + Server momentum.

    Client-side: Each client maintains a gradient tracker h_i approximating
    the accumulated gradient discrepancy. Local objective is augmented with:
        L = ce_loss - <h_i - h_global, w> + (alpha/2) * ||w - w_global||^2
    The linear term aligns local and global gradients; the quadratic term
    prevents aggressive drift.

    Server-side: Exponential moving average (momentum) of model deltas
    smooths the global trajectory and dampens oscillations from
    heterogeneous updates. h_global is updated as average of selected h_i.
    """

    def __init__(self, global_model, args):
        self.args = args
        self.alpha = 0.01          # dynamic regularization strength
        self.beta = 0.9            # server momentum coefficient
        self.momentum = None
        # Per-client gradient trackers h_i
        self.h_clients = {}
        # Global gradient tracker h (average of h_i)
        self.h_global = OrderedDict(
            (k, torch.zeros_like(v, device="cpu"))
            for k, v in global_model.state_dict().items()
            if v.is_floating_point()
        )

    def client_local_train(self, global_state_dict, client_dataset, model_fn,
                           loss_fn, local_epochs, local_lr, local_batch_size,
                           device, client_idx):
        model = model_fn()
        model.load_state_dict(global_state_dict)
        model.to(device)
        model.train()

        # Initialize h_i for this client if needed
        if client_idx not in self.h_clients:
            self.h_clients[client_idx] = OrderedDict(
                (k, torch.zeros_like(v, device="cpu"))
                for k, v in global_state_dict.items()
                if v.is_floating_point()
            )

        # Move trackers to device
        h_i_dev = OrderedDict(
            (k, v.to(device)) for k, v in self.h_clients[client_idx].items()
        )
        h_g_dev = OrderedDict(
            (k, v.to(device)) for k, v in self.h_global.items()
        )

        # Snapshot global parameters for quadratic penalty
        w0 = OrderedDict(
            (n, p.detach().clone())
            for n, p in model.named_parameters()
            if p.requires_grad and n in h_i_dev
        )

        optimizer = optim.SGD(model.parameters(), lr=local_lr)
        loader = DataLoader(client_dataset, batch_size=local_batch_size,
                            shuffle=True, drop_last=False, num_workers=0)

        total_loss, total_samples = 0.0, 0
        for _ in range(local_epochs):
            for inp, tgt in loader:
                if len(inp) == 0:
                    continue
                inp, tgt = inp.to(device), tgt.to(device)
                optimizer.zero_grad()
                out = model(inp)
                if out.dim() == 3:
                    out = out.view(-1, out.size(-1))
                    tgt = tgt.view(-1)
                ce = loss_fn(out, tgt)

                # Dynamic regularization: -<h_i - h_global, w> + (alpha/2)*||w - w0||^2
                reg = 0.0
                for n, p in model.named_parameters():
                    if p.requires_grad and n in h_i_dev:
                        reg = reg - (h_i_dev[n] - h_g_dev[n]).dot(p.view(-1))
                        reg = reg + 0.5 * self.alpha * (p - w0[n]).pow(2).sum()

                (ce + reg).backward()
                optimizer.step()
                total_loss += ce.item() * inp.size(0)
                total_samples += inp.size(0)

        avg_loss = total_loss / max(total_samples, 1)
        final_state = model.cpu().state_dict()
        return final_state, len(client_dataset), avg_loss

    def aggregate(self, global_state_dict, client_updates, round_num):
        """Server momentum aggregation + h_global update."""
        total_samples = sum(max(u[1], 1) for u in client_updates)

        # Compute weighted average delta
        avg_delta = OrderedDict()
        new_state = OrderedDict()
        for key, ref in global_state_dict.items():
            if not ref.is_floating_point():
                new_state[key] = client_updates[0][0][key].detach().clone()
                continue
            avg = torch.zeros_like(ref, dtype=torch.float32)
            for st, n, _ in client_updates:
                avg += st[key].detach().cpu().float() * (max(n, 1) / total_samples)
            avg_delta[key] = avg - ref.float()
            new_state[key] = avg.to(ref.dtype)

        # Initialize momentum buffer on first call
        if self.momentum is None:
            self.momentum = {k: torch.zeros_like(v) for k, v in avg_delta.items()}

        # Update momentum: m = beta * m + (1 - beta) * delta
        for k in avg_delta:
            self.momentum[k] = (
                self.beta * self.momentum[k] + (1.0 - self.beta) * avg_delta[k]
            )

        # Apply momentum to global model
        for k in new_state:
            if k in self.momentum:
                new_state[k] = (global_state_dict[k].float() + self.momentum[k]).to(
                    global_state_dict[k].dtype
                )

        return new_state

    def select_clients(self, num_available, num_to_select, round_num):
        """Uniform random client selection."""
        return random.sample(range(num_available), min(num_to_select, num_available))
